def write():
 ref=load_reference(ROOT);m=ref['metrics']['Base'];tests=json.loads((ROOT/'Testes_Seletores.json').read_text());extra=json.loads((ROOT/'Testes_Seletores_Adicionais.json').read_text()) if (ROOT/'Testes_Seletores_Adicionais.json').exists() else {'tests':[]};testlist=tests['tests']+extra['tests'];val=json.loads((ROOT/'Validacao_Financeira.json').read_text());oox=json.loads((ROOT/'Auditoria_OOXML.json').read_text());passed=sum(t['status']=='PASS' for t in testlist)
